CREATE TABLE god2_research._xjz_stage_loot_or_choice_pool (
  id INT PRIMARY KEY,
  pool_code VARCHAR(128) NOT NULL,
  pool_type VARCHAR(96) NOT NULL,
  source_item_id INT NULL,
  choice_item_id INT NULL,
  choice_name_zh_tw VARCHAR(160) NULL,
  quantity_min INT NULL,
  quantity_max INT NULL,
  weight INT NULL,
  packet_evidence_boundary INT NOT NULL,
  raw_source VARCHAR(255) NOT NULL,
  raw_line INT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE god2_research._xjz_stage_reward_pool_capture_target (
