CREATE TABLE IF NOT EXISTS god2_research.xjz_reward_pool_entries (
  entry_id INT NOT NULL,
  pool_code VARCHAR(128) NOT NULL,
  pool_type_zh_tw VARCHAR(128) NOT NULL,
  source_item_id INT NULL,
  linked_formal_source_item_id BIGINT NULL,
  choice_item_id INT NULL,
  linked_formal_choice_item_id BIGINT NULL,
  choice_name_zh_tw VARCHAR(160) NULL,
  quantity_min INT NULL,
  quantity_max INT NULL,
  weight INT NULL,
  weight_status_zh_tw VARCHAR(64) NOT NULL,
  source_line INT NULL,
  needs_packet_evidence INT NOT NULL,
  PRIMARY KEY (entry_id),
  KEY ix_xjz_reward_pool_code (pool_code),
  KEY ix_xjz_reward_pool_choice_link (linked_formal_choice_item_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='C#證據包：福袋、選擇池、獎勵池候選項目。';

CREATE TABLE IF NOT EXISTS god2_research.xjz_reward_pool_capture_targets (
  target_id INT NOT NULL,
