DELETE FROM god2_research.xjz_reward_pool_entries;
SELECT
  p.id,
  p.pool_code,
  CASE p.pool_type WHEN 'fudai_pool_entry' THEN '福袋獎池項目' WHEN 'fudai_total_pool_entry' THEN '滿額福袋獎池項目' WHEN 'roulette_pool_entry' THEN '轉盤獎池項目' ELSE p.pool_type END,
  p.source_item_id,
  src.item_id,
  p.choice_item_id,
  choice_item.item_id,
  p.choice_name_zh_tw,
  p.quantity_min,
  p.quantity_max,
  p.weight,
  CASE WHEN p.weight IS NULL THEN '缺權重，需實測' ELSE '有候選權重' END,
  p.raw_line,
  p.packet_evidence_boundary
FROM god2_research._xjz_stage_loot_or_choice_pool p
LEFT JOIN god2_game.items src ON src.client_item_id = p.source_item_id
LEFT JOIN god2_game.items choice_item ON choice_item.client_item_id = p.choice_item_id;

DELETE FROM god2_research.xjz_reward_pool_capture_targets;
SELECT
  t.target_id,
  t.pool_code,
  CASE t.primary_pool_type WHEN 'fudai_pool_entry' THEN '福袋獎池項目' WHEN 'fudai_total_pool_entry' THEN '滿額福袋獎池項目' WHEN 'roulette_pool_entry' THEN '轉盤獎池項目' ELSE t.primary_pool_type END,
  t.source_item_id,
  src.item_id,
  t.entry_count,
  t.distinct_item_count,
  t.display_slot_count,
  CASE t.capture_priority WHEN 'high' THEN '高' WHEN 'medium' THEN '中' ELSE t.capture_priority END,
  t.capture_context,
  REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(t.wanted_fields_json, '"raw_packet"', '原始封包'), '"pool_code"', '獎池代碼'), '"source_item_id"', '來源道具ID'), '"result_item_json"', '結果道具'), '"observed_weight"', '觀測權重'),
  t.target_pool_table,
  t.target_roll_sample_table,
  t.target_choice_sample_table,
  t.target_grant_sample_table,
  t.request_hint_zh_tw,
  t.current_client_source,
  t.raw_line_min,
  t.raw_line_max,
  t.evidence_status,
  t.packet_evidence_boundary
FROM god2_research._xjz_stage_reward_pool_capture_target t
LEFT JOIN god2_game.items src ON src.client_item_id = t.source_item_id;

DELETE FROM god2_research.xjz_reward_pool_playbook_routes;
SELECT
  route_binding_id,
  target_id,
  step_id,
  CASE action_key WHEN 'reward_pool_flow' THEN '獎勵池流程' ELSE action_key END,
  pool_code,
  CASE primary_pool_type WHEN 'fudai_pool_entry' THEN '福袋獎池項目' WHEN 'fudai_total_pool_entry' THEN '滿額福袋獎池項目' WHEN 'roulette_pool_entry' THEN '轉盤獎池項目' ELSE primary_pool_type END,
  source_item_id,
  entry_count,
  distinct_item_count,
  display_slot_count,
  capture_context,
  target_pool_table,
  target_sample_table,
  CASE target_sample_role WHEN 'roll_sample' THEN '抽選樣本' WHEN 'choice_sample' THEN '選擇樣本' WHEN 'grant_sample' THEN '授予樣本' ELSE target_sample_role END,
  route_id,
  query_id,
  CASE route_state WHEN 'enabled' THEN '啟用' ELSE route_state END,
  evidence_status,
  packet_evidence_boundary
FROM god2_research._xjz_stage_reward_pool_playbook_route;

DELETE FROM god2_research.xjz_reward_pool_service_summary;
SELECT
  s.service_id,
  s.pool_code,
  CASE s.primary_pool_type WHEN 'fudai_pool_entry' THEN '福袋獎池項目' WHEN 'fudai_total_pool_entry' THEN '滿額福袋獎池項目' WHEN 'roulette_pool_entry' THEN '轉盤獎池項目' ELSE s.primary_pool_type END,
  s.source_item_id,
  src.item_id,
  s.source_item_name_zh_tw,
  s.entry_count,
  s.distinct_item_count,
  s.display_slot_count,
  s.weighted_entry_count,
  s.missing_weight_count,
  s.capture_context,
  CASE s.capture_priority WHEN 'high' THEN '高' WHEN 'medium' THEN '中' ELSE s.capture_priority END,
  s.target_roll_sample_table,
  s.target_choice_sample_table,
  s.target_grant_sample_table,
  s.raw_line_min,
  s.raw_line_max,
  s.evidence_status,
  s.packet_evidence_boundary
FROM god2_research._xjz_stage_reward_pool_service_template s
LEFT JOIN god2_game.items src ON src.client_item_id = s.source_item_id;

DELETE FROM god2_research.xjz_roulette_display_evidence;
SELECT
  r.roulette_display_id,
  r.pool_code,
  r.display_slot,
  r.display_item_id,
  i.item_id,
  r.display_name_zh_tw,
  r.linked_pool_entry_id,
  r.raw_line,
  r.evidence_status,
  r.packet_evidence_boundary
FROM god2_research._xjz_stage_roulette_display_template r
LEFT JOIN god2_game.items i ON i.client_item_id = r.display_item_id;

CREATE OR REPLACE VIEW god2_research.vw_xjz_reward_pool_csharp_summary_zh_tw AS
SELECT '獎勵池候選項目' AS 資料類型, COUNT(*) AS 筆數, SUM(CASE WHEN linked_formal_choice_item_id IS NOT NULL THEN 1 ELSE 0 END) AS 已連正式道具, SUM(CASE WHEN weight IS NULL THEN 1 ELSE 0 END) AS 缺權重, SUM(needs_packet_evidence) AS 需要封包證據, '福袋、滿額福袋、轉盤候選獎項' AS 遊戲功能
FROM god2_research.xjz_reward_pool_entries
UNION ALL
SELECT '獎勵池抓包目標', COUNT(*), SUM(CASE WHEN linked_formal_source_item_id IS NOT NULL THEN 1 ELSE 0 END), NULL, SUM(needs_packet_evidence), '抽選、選擇、授予結果抓包'
FROM god2_research.xjz_reward_pool_capture_targets
UNION ALL
SELECT '獎勵池Playbook路線', COUNT(*), NULL, NULL, SUM(needs_packet_evidence), '正式抓包流程路線'
FROM god2_research.xjz_reward_pool_playbook_routes
UNION ALL
SELECT '獎勵池服務摘要', COUNT(*), SUM(CASE WHEN linked_formal_source_item_id IS NOT NULL THEN 1 ELSE 0 END), SUM(missing_weight_count), SUM(needs_packet_evidence), '服務端獎勵池摘要'
FROM god2_research.xjz_reward_pool_service_summary
UNION ALL
SELECT '轉盤顯示項目', COUNT(*), SUM(CASE WHEN linked_formal_display_item_id IS NOT NULL THEN 1 ELSE 0 END), NULL, SUM(needs_packet_evidence), '轉盤畫面三個獎項顯示'
FROM god2_research.xjz_roulette_display_evidence;

UPDATE god2_research.xjz_csharp_zip_evidence_digest
SET current_project_status_zh_tw = '已匯入獎勵池、福袋與轉盤候選',
    safe_apply_level_zh_tw = '可用於研究與抓包；缺權重或來源者不直接成為正式掉落',
    next_server_action_zh_tw = '先用已連正式道具的獎池候選建立只讀對照，再透過抓包樣本確認權重、消耗、授予結果後才提升正式獎勵。',
    blocked_reason_zh_tw = '部分福袋候選缺權重；日常任務獎勵文字有亂碼，已暫不匯入正式可見表。',
    related_project_object_zh_tw = 'migration 458, xjz_reward_pool_*'
WHERE evidence_key = 'reward_pool_sources';

